from pathlib import Path
import ast, hashlib, importlib.metadata as md, json, platform, re, subprocess, sys

ROOT = Path(r'C:\TORMENT\TRIOCTAGON_new\trioctagon-physics')
OUT = Path(__file__).parent
tracked = subprocess.check_output(['git', '-C', str(ROOT), 'ls-files', '-z']).decode().split('\0')[:-1]
runtime = {p.stem: p for p in (ROOT / 'kernel_physics').glob('*.py')}
nodes = {}
for name, path in sorted(runtime.items()):
    source = path.read_text(encoding='utf-8-sig')
    imports = []
    for node in ast.walk(ast.parse(source)):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            targets = []
            if isinstance(node, ast.Import):
                targets = [v.name for v in node.names]
            elif node.level:
                targets = [f'kernel_physics.{node.module}'] if node.module else [
                    f'kernel_physics.{v.name}' if v.name in runtime else 'kernel_physics.__init__' for v in node.names]
            else:
                targets = [node.module]
            imports.append({'line': node.lineno, 'statement': ast.get_source_segment(source, node), 'targets': targets})
    nodes[name] = {'path': path.relative_to(ROOT).as_posix(), 'sha256': hashlib.sha256(path.read_bytes()).hexdigest(), 'imports': imports}
closure = {'api', '__init__'}
while True:
    expanded = closure | {t.split('.')[-1] for n in closure for row in nodes[n]['imports'] for t in row['targets'] if t.startswith('kernel_physics.')}
    if expanded == closure:
        break
    closure = expanded
quarantine = {'boundary_response','srg','operating_region'}
for name, data in nodes.items():
    for row in data['imports']:
        row['classifications'] = {}
        for target in row['targets']:
            base = target.split('.')[0]
            if base in sys.stdlib_module_names:
                label = 'STDLIB'
            elif base == 'kernel_physics':
                leaf = target.split('.')[-1]
                label = 'QUARANTINED' if leaf in quarantine else 'REQUIRED_RUNTIME_DEPENDENCY' if leaf in closure else 'OPTIONAL_RUNTIME_DEPENDENCY'
            else:
                label = 'REQUIRED_RUNTIME_DEPENDENCY'
            row['classifications'][target] = label
third_party = sorted({t.split('.')[0] for n in closure for r in nodes[n]['imports'] for t in r['targets'] if t.split('.')[0] not in sys.stdlib_module_names and not t.startswith('kernel_physics.')})
test_imports = set()
for path in tracked:
    if path.startswith('kernel_physics/tests/') and path.endswith('.py'):
        for node in ast.walk(ast.parse((ROOT/path).read_text(encoding='utf-8-sig'))):
            if isinstance(node, ast.Import):
                test_imports.update(a.name.split('.')[0] for a in node.names)
            elif isinstance(node, ast.ImportFrom) and node.level == 0:
                test_imports.add(node.module.split('.')[0])
dependency_metadata = {}
for name in [*third_party, 'pip', 'setuptools', 'wheel', 'build']:
    try:
        dist = md.distribution(name)
        dependency_metadata[name] = {'version':dist.version, 'requires_python':dist.metadata.get('Requires-Python'), 'requires_dist':dist.requires or []}
    except md.PackageNotFoundError:
        dependency_metadata[name] = {'present':False}
special = {'pyproject.toml','setup.py','setup.cfg','MANIFEST.in','tox.ini','noxfile.py','pytest.ini'}
def metadata_path(p):
    name = Path(p).name
    return name in special or bool(re.fullmatch(r'(requirements.*\.txt|environment.*\.ya?ml|conda.*\.ya?ml)',name)) or '/.github/workflows/' in '/' + p
census = {p:(ROOT/p).read_text(encoding='utf-8-sig') for p in tracked if metadata_path(p)}
readmes = [p for p in tracked if Path(p).name.lower().startswith('readme')]
licenses = [p for p in tracked if re.search(r'license|licence|copying|notice',Path(p).name,re.I)]
pattern = re.compile(r'\b(requests|urllib|httpx|socket|huggingface|transformers|torch|tensorflow|cuda|openai|urlopen|pip\s+install|git\s+(fetch|pull|clone))\b',re.I)
network_hits = [{'path':nodes[n]['path'],'line':i,'text':line} for n in closure for i,line in enumerate((ROOT/nodes[n]['path']).read_text().splitlines(),1) if pattern.search(line)]
result = {'tracked_count':len(tracked),'metadata_files':census,'readmes':readmes,'license_named_files':licenses,'runtime_modules':nodes,'public_closure':sorted(closure),'public_closure_count':len(closure),'required_third_party':third_party,'stdlib_imports':sorted({t for n in closure for r in nodes[n]['imports'] for t in r['targets'] if t.split('.')[0] in sys.stdlib_module_names}),'test_imports':sorted(test_imports),'test_only_third_party':sorted(test_imports-set(third_party)-sys.stdlib_module_names-{'kernel_physics'}),'dependency_metadata':dependency_metadata,'network_model_scan_hits':network_hits,'python':platform.python_version(),'platform':platform.platform(),'executable':sys.executable}
(OUT/'static_audit.json').write_text(json.dumps(result,indent=2),encoding='utf-8')
print(json.dumps({k:v for k,v in result.items() if k not in ('runtime_modules','metadata_files','readmes','dependency_metadata')},indent=2))
print(json.dumps({'dependency_metadata':dependency_metadata},indent=2))
